    box(-11,-8,14,4,'#687e70','#344f42');for(var q=0;q<2;q++){c.fillStyle='#1b282b';c.beginPath();c.arc(q?9:-8,9,3.4,0,6.3);c.fill();ring(q?9:-8,9,1.4,'#899b8c',1);}
    line(-10,-2,1,-2,'#d0c391',.7);
